// ---- web/lib/portfolio.js
const __portfolio = (() => {
/* Portfolio maths (CLAUDE.md 13.13.3) — pure functions, tested in tests/js/portfolio.test.mjs.
 * Positions come from the transactions table (buy / sell / starting position), average-cost method.
 * Money in EUR: fx = {USD: 1.08} means 1 EUR = 1.08 USD. Realised gains per tax rules come in 3C. */

const BUCKET = {
  broad_etf: "core", bond_etf: "core", sector_etf: "satellite", stock: "satellite", other: "satellite",
  speculative: "speculative", crypto: "speculative",
};

/** Amount in `currency` → EUR, using today's rate (EUR itself → as is). */
function toEur(amount, currency, fx) {
  if (amount == null) return null;
  if (!currency || currency === "EUR") return amount;
  const r = fx?.[currency];
  return r ? amount / r : null;
}

/** Transactions → positions {symbol, qty, currency, avgCost (per share, incl. fees, trade currency), costEur, realised}. */
function positions(transactions) {
  const by = new Map();
  const sorted = [...(transactions || [])].sort((a, b) => a.date.localeCompare(b.date) || String(a.created_at || "").localeCompare(String(b.created_at || "")));
  for (const t of sorted) {
    if (t.kind === "dividend") continue; // income, not a change in what you own (see lib/dividends.js)
    const sym = t.symbol.toUpperCase();
    const p = by.get(sym) || { symbol: sym, qty: 0, cost: 0, costEur: 0, currency: t.currency, realised: 0, realisedEur: 0, firstDate: t.date, trades: 0 };
    const rate = t.fx_rate || null; // units per EUR at the trade, if known
    const extra = (Number(t.fees) || 0) + (Number(t.taxes) || 0);
    if (t.kind === "buy" || t.kind === "start") {
      const c = t.quantity * t.price + extra;
      p.qty += Number(t.quantity);
      p.cost += c;
      p.costEur += rate ? c / rate : t.currency === "EUR" ? c : NaN; // NaN → valued with today's rate later
    } else if (t.kind === "sell" && p.qty > 0) {
      const q = Math.min(Number(t.quantity), p.qty);
      const avg = p.cost / p.qty;
      const avgEur = p.costEur / p.qty;
      const proceeds = q * t.price - extra;
      p.realised += proceeds - q * avg;
      if (rate) p.realisedEur += proceeds / rate - q * avgEur;
      p.cost -= q * avg;
      p.costEur -= q * avgEur;
      p.qty -= q;
    }
    p.trades += 1;
    by.set(sym, p);
  }
  return [...by.values()].map((p) => ({ ...p, avgCost: p.qty > 0 ? p.cost / p.qty : null }));
}

/**
 * Value everything in EUR.
 * rows: watchlist rows {symbol, name, price, currency, change_pct, asset_type, risk{suggested_type, sector, region, vol}, quality, verdict, score…}
 * settings: {cash: {EUR, USD}, emergency_fund}
 * Returns {holdings[], invested, cash, total, dayChange, pl, plPct, cost, buckets{}, alloc{type,sector,region,currency}}.
 */
function valuePortfolio(transactions, rows, settings, fx) {
  const bySym = Object.fromEntries((rows || []).map((r) => [r.symbol.toUpperCase(), r]));
  const holdings = [];
  for (const p of positions(transactions)) {
    if (p.qty <= 1e-9) continue;
    const r = bySym[p.symbol] || {};
    const priced = r.price != null && !r.error;
    const currency = priced ? r.currency : p.currency;
    const price = priced ? r.price : p.avgCost; // new holding: valued at cost until tonight's update
    const value = toEur(p.qty * price, currency, fx);
    const costEur = Number.isFinite(p.costEur) ? p.costEur : toEur(p.cost, p.currency, fx);
    const type = r.asset_type || r.risk?.suggested_type || "stock";
    const chg = priced && r.change_pct != null ? value - value / (1 + r.change_pct / 100) : 0;
    holdings.push({
      symbol: p.symbol, name: r.name || p.symbol, qty: p.qty, price, currency, priced, value, costEur,
      pl: value != null && costEur != null ? value - costEur : null,
      plPct: value != null && costEur ? (value / costEur - 1) * 100 : null,
      dayChange: chg, change_pct: priced ? r.change_pct : null, type, bucket: BUCKET[type] || "satellite",
      sector: r.risk?.sector || null, region: r.risk?.region || null, row: r,
    });
  }
  const cashIn = settings?.cash || {};
  const cash = Object.entries(cashIn).reduce((s, [cur, v]) => s + (toEur(Number(v) || 0, cur, fx) || 0), 0);
  const invested = holdings.reduce((s, h) => s + (h.value || 0), 0);
  const total = invested + cash;
  const cost = holdings.reduce((s, h) => s + (h.costEur || 0), 0);
  const dayChange = holdings.reduce((s, h) => s + (h.dayChange || 0), 0);
  for (const h of holdings) h.weight = total ? (h.value / total) * 100 : 0;

  const group = (key) => {
    const m = {};
    for (const h of holdings) {
      // broad and bond ETFs spread themselves over many sectors/regions (look-through comes in a later stage)
      const k = (key === "sector" || key === "region") && h.bucket === "core" ? "spread" : h[key] || "unknown";
      m[k] = (m[k] || 0) + h.value;
    }
    if (key === "bucket" || key === "type") m.cash = cash;
    return Object.fromEntries(Object.entries(m).filter(([, v]) => v > 0).sort((a, b) => b[1] - a[1]).map(([k, v]) => [k, { value: v, pct: total ? (v / total) * 100 : 0 }]));
  };
  const curAlloc = {};
  for (const h of holdings) curAlloc[h.currency] = (curAlloc[h.currency] || 0) + h.value;
  for (const [c, v] of Object.entries(cashIn)) curAlloc[c] = (curAlloc[c] || 0) + (toEur(Number(v) || 0, c, fx) || 0);
  return {
    holdings: holdings.sort((a, b) => b.value - a.value), invested, cash, total, cost, dayChange,
    dayChangePct: total - dayChange ? (dayChange / (total - dayChange)) * 100 : 0,
    pl: invested - cost, plPct: cost ? (invested / cost - 1) * 100 : 0,
    buckets: group("bucket"),
    alloc: {
      type: group("type"), sector: group("sector"), region: group("region"),
      currency: Object.fromEntries(Object.entries(curAlloc).filter(([, v]) => v > 0).sort((a, b) => b[1] - a[1]).map(([k, v]) => [k, { value: v, pct: total ? (v / total) * 100 : 0 }])),
    },
  };
}

/** Position cap (%) for one holding under the settings: quality stocks get the higher stock cap. */
function typeCap(type, qualityScore, settings) {
  const caps = settings.type_caps || {};
  if (type === "stock") return qualityScore != null && qualityScore >= 70 ? caps.stock_quality : caps.stock;
  return caps[type] ?? null;
}

/** Warnings with the rule and what to do (8.10): [{kind, symbol?, key, vars}]. */
function warnings(pf, settings) {
  const out = [];
  if (!pf.total) return out;
  for (const h of pf.holdings) {
    const cap = typeCap(h.type, h.row?.quality?.score, settings);
    if (cap != null && h.weight > cap + 0.05) out.push({ key: "overCap", symbol: h.symbol, vars: { symbol: h.symbol, weight: h.weight, cap } });
  }
  for (const [sector, v] of Object.entries(pf.alloc.sector)) {
    if (sector !== "unknown" && sector !== "spread" && v.pct > settings.sector_max + 0.05) out.push({ key: "sectorOver", vars: { sector, pct: v.pct, max: settings.sector_max } });
  }
  const sat = pf.buckets.satellite?.pct || 0;
  const spec = pf.buckets.speculative?.pct || 0;
  if (sat + spec > settings.satellite_max + 0.05) out.push({ key: "satelliteOver", vars: { pct: sat + spec, max: settings.satellite_max } });
  if (spec > settings.speculative_max + 0.05) out.push({ key: "speculativeOver", vars: { pct: spec, max: settings.speculative_max } });
  const cashPct = (pf.cash / pf.total) * 100;
  if (cashPct < settings.cash_reserve - 0.05) out.push({ key: "cashLow", vars: { pct: cashPct, min: settings.cash_reserve } });
  return out;
}

return { BUCKET, toEur, positions, valuePortfolio, typeCap, warnings };
})();

// ---- web/lib/sizing.js
const __sizing = (() => {
/* Position sizing engine (CLAUDE.md 13.13.4) — pure and deterministic, tested in tests/js/sizing.test.mjs
 * with the worked example from 13.13.5. Never places trades; every number says which rule set it. */
const { BUCKET, typeCap } = __portfolio;

/**
 * pf: valuePortfolio() result (total, cash, holdings, buckets, alloc)
 * c: candidate {symbol, type, vol, max_dd, quality (0–100|null), verdict, sector, region, earnings_in_days}
 * s: settings (risk_per_position, k, satellite_max, speculative_max, cash_reserve, type_caps, sector_max, region_max,
 *    multipliers, typical_vol)
 * Returns {total, owned, maxPosition, room, limiting, rules[], calc{}, notes[]}; rules = [{key, room, cap?, vars}].
 */
function sizeFor(pf, c, s) {
  const total = pf.total;
  const owned = pf.holdings.find((h) => h.symbol === c.symbol)?.value || 0;
  const type = c.type || "stock";
  const bucket = BUCKET[type] || "satellite";
  const notes = [];

  // ---- 1. risk per position: max loss ÷ bad-case drop, adjusted for quality and verdict
  let vol = c.vol;
  if (vol == null || !(vol > 0)) { vol = s.typical_vol?.[type] ?? 0.35; notes.push("typicalVol"); }
  let bad = s.k * vol;
  if (c.max_dd != null && c.max_dd > 0 && c.max_dd < bad) { bad = c.max_dd; notes.push("cappedByDrawdown"); }
  bad = Math.min(Math.max(bad, 0.05), 1);
  const maxLoss = total * (s.risk_per_position / 100);
  const base = maxLoss / bad;
  const m = s.multipliers || {};
  const isStock = type === "stock";
  let qMult = 1;
  if (isStock && c.quality != null) qMult = c.quality >= 70 ? m.quality_high : c.quality >= 40 ? m.quality_medium : m.quality_low;
  const vMult = c.verdict === "sale" ? m.verdict_sale : c.verdict === "trap" ? m.verdict_trap : 1;
  const cMult = c.correlated ? m.correlated : 1;
  const riskAmount = base * qMult * vMult * cMult;
  const rules = [{ key: "risk", room: riskAmount - owned, cap: riskAmount, vars: { pct: s.risk_per_position } }];

  // ---- 2. type cap (one position)
  const capPct = typeCap(type, c.quality, s);
  if (capPct != null) rules.push({ key: "typeCap", room: (total * capPct) / 100 - owned, cap: (total * capPct) / 100, vars: { pct: capPct, type } });

  // ---- 3. sector / region headroom (broad and bond ETFs don't count: they spread themselves)
  if (bucket !== "core" && c.sector) {
    const used = pf.alloc.sector?.[c.sector]?.value || 0;
    rules.push({ key: "sector", room: (total * s.sector_max) / 100 - used, vars: { sector: c.sector, pct: s.sector_max } });
  }
  if (bucket !== "core" && c.region && s.region_max != null) {
    const used = pf.alloc.region?.[c.region]?.value || 0;
    rules.push({ key: "region", room: (total * s.region_max) / 100 - used, vars: { region: c.region, pct: s.region_max } });
  }

  // ---- 4. core–satellite split
  const satUsed = (pf.buckets.satellite?.value || 0) + (pf.buckets.speculative?.value || 0);
  if (bucket !== "core") rules.push({ key: "satellite", room: (total * s.satellite_max) / 100 - satUsed, vars: { pct: s.satellite_max } });
  if (bucket === "speculative") {
    rules.push({ key: "speculative", room: (total * s.speculative_max) / 100 - (pf.buckets.speculative?.value || 0), vars: { pct: s.speculative_max } });
  }

  // ---- 5. cash you can actually use (minus the reserve)
  rules.push({ key: "cash", room: pf.cash - (total * s.cash_reserve) / 100, vars: { pct: s.cash_reserve } });

  let limiting = rules[0];
  for (const r of rules) if (r.room < limiting.room) limiting = r;
  const room = Math.max(0, limiting.room);
  if (c.earnings_in_days != null && c.earnings_in_days >= 0 && c.earnings_in_days <= 7) notes.push("earningsSoon");
  return {
    total, owned, room, maxPosition: owned + room, limiting: limiting.key, limitingCap: limiting.cap ?? null, rules,
    calc: { maxLoss, vol, k: s.k, bad, base, qMult, vMult, cMult, riskAmount },
    notes,
  };
}

/** Staged buy plan (13.13.5): split the room in 3 — now, nearest support, 200-week average (or −20 % / −30 %). */
function stagedPlan(room, price, { support = null, sma200 = null } = {}) {
  if (!(room > 0) || !(price > 0)) return [];
  const part = room / 3;
  const levels = [];
  if (support && support < price) levels.push({ at: support, why: "support" });
  if (sma200 && sma200 < price * 0.98 && !levels.some((l) => Math.abs(l.at / sma200 - 1) < 0.03)) levels.push({ at: sma200, why: "sma200" });
  for (const d of [0.8, 0.7]) if (levels.length < 2) levels.push({ at: price * d, why: d === 0.8 ? "minus20" : "minus30" });
  levels.sort((a, b) => b.at - a.at);
  return [{ at: null, why: "now", amount: part }, ...levels.slice(0, 2).map((l) => ({ ...l, amount: part }))];
}

/** Does `amount` fit? {fits, over} */
function check(amount, result) {
  if (!(amount > 0)) return null;
  return amount <= result.room + 0.5 ? { fits: true, over: 0 } : { fits: false, over: amount - result.room };
}

return { sizeFor, stagedPlan, check };
})();

// ---- web/lib/thesis.js
const __thesis = (() => {
/* Thesis checks (CLAUDE.md 13.14 D) — same rules as src/thesis.py (shared cases in
 * tests/fixtures/thesis_cases.json). Metric values come from latest_scores.metrics (daily job). */

// unit and decimals for showing each metric; the order is the order in the rule picker
const METRICS = {
  quality_score: { unit: "pts", dec: 0 },
  sales_growth: { unit: "%", dec: 1 },
  operating_margin: { unit: "%", dec: 1 },
  net_debt_ebitda: { unit: "x", dec: 2 },
  interest_cover: { unit: "x", dec: 1 },
  roic: { unit: "%", dec: 1 },
  fcf_years: { unit: "yrs", dec: 0 },
  share_change: { unit: "%", dec: 1 },
  bottom_score: { unit: "pts", dec: 0 },
  from_high: { unit: "%", dec: 1 },
};

const num = (v) => (v === null || v === undefined || v === "" || !Number.isFinite(Number(v)) ? null : Number(v));

/** Each rule {metric, op, value} with the actual value and ok (null = unknown). */
function evaluate(rules, metrics) {
  return (rules || []).map((r) => {
    const actual = num(metrics?.[r.metric]);
    const target = num(r.value);
    let ok = null;
    if (actual != null && target != null && (r.op === ">=" || r.op === "<=")) ok = r.op === ">=" ? actual >= target : actual <= target;
    return { ...r, actual, ok };
  });
}

/** none · unknown · intact · broken1 · broken */
function status(results) {
  if (!results?.length) return "none";
  const broken = results.filter((r) => r.ok === false).length;
  if (broken >= 2) return "broken";
  if (broken === 1) return "broken1";
  return results.some((r) => r.ok === true) ? "intact" : "unknown";
}

return { METRICS, evaluate, status };
})();

// ---- backend/functions/telegram-bot/core.js
const __core = (() => {
/* Telegram bot commands (CLAUDE.md 13.16 B) — pure: text in, data in, reply text out.
 * Read-only: no command can change anything. Reuses the app's tested portfolio, sizing and thesis code.
 * Tested in tests/js/bot.test.mjs; bundled into index.ts by scripts/build_bot.py. */
const { valuePortfolio } = __portfolio;
const { sizeFor } = __sizing;
const { settingsFor } = __risk_defaults;
const { evaluate, status: thesisStatus } = __thesis;

const COMMANDS = [
  ["score", "Bottom, Top, Quality and verdict for a ticker"],
  ["portfolio", "Value, today, result, cash and risk budget"],
  ["canibuy", "How much fits your rules, e.g. /canibuy ASML.AS 2000"],
  ["events", "Earnings, dividends and Fed/ECB in the next 7 days"],
  ["levels", "Nearest support and resistance for a ticker"],
  ["thesis", "Thesis status and rules for a holding"],
  ["news", "Latest headlines for a ticker"],
  ["health", "Is the data up to date?"],
  ["gaps", "Portfolio gaps (comes later)"],
  ["help", "This list"],
];
const NEEDS = {
  score: ["rows"], portfolio: ["rows", "pf", "market"], canibuy: ["rows", "pf", "market"], events: ["rows", "macro"],
  levels: ["rows", "detail"], thesis: ["rows", "pf"], news: ["rows", "detail"], health: ["runs"], gaps: [], help: [],
};
const needs = (cmd) => NEEDS[cmd] || [];

/** "/canibuy@MyBot asml.as 2.000" → {cmd: "canibuy", args: ["ASML.AS", "2.000"]} */
function parseCommand(text) {
  const m = String(text || "").trim().match(/^\/([a-z_]+)(?:@\w+)?\s*(.*)$/i);
  if (!m) return { cmd: "help", args: [] };
  const cmd = m[1].toLowerCase();
  const args = m[2].split(/\s+/).filter(Boolean).map((a, i) => (i === 0 ? a.toUpperCase() : a));
  return { cmd: NEEDS[cmd] ? cmd : "unknown", args, raw: m[1] };
}

/* ---------------------------------------------------------------- formatting (nl-BE) */
const nf = (d) => new Intl.NumberFormat("nl-BE", { minimumFractionDigits: d, maximumFractionDigits: d });
const num = (v, d = 0) => (v == null || !Number.isFinite(Number(v)) ? "n/a" : nf(d).format(v));
const money = (v, cur = "EUR", d = 0) => (v == null ? "n/a" : `${{ EUR: "€", USD: "$", GBP: "£" }[cur] || `${cur} `}${cur in { EUR: 1, USD: 1, GBP: 1 } ? " " : ""}${num(v, d)}`);
const pct = (v, d = 1) => (v == null ? "n/a" : `${num(v, d)} %`);
const signed = (v, d = 1) => (v == null ? "n/a" : `${v >= 0 ? "▲ +" : "▼ −"}${num(Math.abs(v), d)} %`);
const smart = (v) => num(v, v != null && Number.isInteger(Number(v)) ? 0 : 1);
const signedEur = (v) => `${v >= 0 ? "+" : "−"}${money(Math.abs(v))}`;
/** "2.000" (Belgian) or "2000" or "2,5" → number */
const parseAmount = (s) => {
  const t = String(s || "").replace(/[€\s]/g, "");
  if (!t) return NaN;
  return Number(/,/.test(t) ? t.replace(/\./g, "").replace(",", ".") : /^\d{1,3}(\.\d{3})+$/.test(t) ? t.replace(/\./g, "") : t);
};
const link = (app, path) => `▶ ${app.replace(/\/$/, "")}/#/${path}`;
const LABEL = { normal: "Normal", watch: "Watch", strong: "Strong", extreme: "Extreme" };
const VERDICT = { sale: "🟢 Quality on sale", check: "🟡 Check fundamentals", trap: "🔴 Possible value trap", none: "⚪ Not at a bottom" };
const RULE = {
  risk: "max loss per position", typeCap: "cap for this asset type", sector: "sector maximum", region: "region maximum",
  satellite: "satellite maximum", speculative: "speculative maximum", cash: "your cash minus the reserve",
};
const SIGNAL = {
  T1: "near its 200-week average", T2: "weekly RSI oversold", T3: "≥ 30 % below its high", T4: "near a major previous bottom",
  V1: "cheap vs its own history", V2: "insiders buying", S1: "market fearful",
};

function findRow(data, sym) {
  return (data.rows || []).find((r) => r.symbol === sym) || null;
}
const needTicker = (cmd) => `Which ticker? e.g. /${cmd} NVDA`;
const notOnList = (sym) => `${sym} isn't on your watchlist. Add it in the app first.`;

/* ---------------------------------------------------------------- replies */
function help() {
  return ["Bottom Tracker (read-only):", ...COMMANDS.map(([c, d]) => `/${c} — ${d}`)].join("\n");
}

function score(data, sym, app) {
  if (!sym) return needTicker("score");
  const r = findRow(data, sym);
  if (!r) return notOnList(sym);
  if (r.error || r.score == null) return `${sym}: no score yet (${r.error || "waiting for tonight's update"}).`;
  const fired = (r.signals || []).filter((s) => s.passed === true).map((s) => SIGNAL[s.code] || s.code);
  const lines = [
    `${sym} · ${money(r.price, r.currency, 2)} (${signed(r.change_pct)} today)`,
    `Bottom Score ${r.score}/${r.max_score} · ${LABEL[r.label] || r.label}`,
    fired.length ? `Fired: ${fired.join(", ")}` : "No bottom signals fired.",
    r.top?.score != null ? `Top Score ${r.top.score}/${r.top.max_score ?? 6}${r.top.score >= 4 ? " · consider trimming" : r.top.score >= 2 ? " · getting hot" : ""}` : null,
    r.quality?.score != null ? `Quality ${Math.round(r.quality.score)}${r.quality.moat ? ` · moat ${r.quality.moat}` : ""}` : "Quality n/a",
    r.verdict ? VERDICT[r.verdict] : null,
    link(app, `ticker/${encodeURIComponent(sym)}`),
  ];
  return lines.filter(Boolean).join("\n");
}

function riskSettings(risk) {
  const base = settingsFor(risk?.profile && risk.profile !== "custom" ? risk.profile : "balanced");
  if (!risk?.settings) return base;
  const s = risk.settings;
  return { ...base, ...s, profile: risk.profile, type_caps: { ...base.type_caps, ...(s.type_caps || {}) },
    multipliers: { ...base.multipliers, ...(s.multipliers || {}) }, typical_vol: base.typical_vol };
}

const fxOf = (data) => data.market?.fx?.rates || {};
const valued = (data) => valuePortfolio(data.pf?.transactions || [], data.rows || [], data.pf?.settings || {}, fxOf(data));

function portfolio(data, app) {
  const pf = valued(data);
  if (!pf.total) return "No portfolio yet. Add your positions in the app (Portfolio → Import from Bolero).";
  const s = riskSettings(data.pf?.risk);
  const b = (k) => pf.buckets[k]?.pct || 0;
  return [
    `Portfolio ${money(pf.total)} · ${signed(pf.dayChangePct)} today (closing prices)`,
    `Since you bought: ${signedEur(pf.pl)} (${signed(pf.plPct)})`,
    `Cash ${money(pf.cash)} (${pct(pf.total ? (pf.cash / pf.total) * 100 : 0, 0)})`,
    `Core ${pct(b("core"), 0)} (min ${pct(s.core_min, 0)}) · satellite ${pct(b("satellite") + b("speculative"), 0)} (max ${pct(s.satellite_max, 0)})`,
    `Largest: ${pf.holdings.slice(0, 3).map((h) => `${h.symbol} ${pct(h.weight, 0)}`).join(", ")}`,
    link(app, "portfolio"),
  ].join("\n");
}

function canibuy(data, sym, amountText, app) {
  if (!sym) return needTicker("canibuy");
  const r = findRow(data, sym);
  if (!r) return notOnList(sym);
  const pf = valued(data);
  if (!pf.total) return "Add your portfolio in the app first, so I know its size.";
  const s = riskSettings(data.pf?.risk);
  const type = r.asset_type || r.risk?.suggested_type || "stock";
  const days = r.next_earnings?.date ? Math.round((Date.parse(`${r.next_earnings.date}T12:00:00Z`) - Date.now()) / 864e5) : null;
  const res = sizeFor(pf, { symbol: sym, type, vol: r.risk?.vol, max_dd: r.risk?.max_dd, quality: r.quality?.score ?? null,
    verdict: r.verdict, sector: r.risk?.sector, region: r.risk?.region, earnings_in_days: days }, s);
  const amount = parseAmount(amountText);
  const lines = [
    res.room > 0 ? `${sym}: up to ${money(res.maxPosition)}${res.owned > 0 ? ` · you own ${money(res.owned)} → room ${money(res.room)}` : ` · room ${money(res.room)}`}`
      : `${sym}: no room to add under your rules.`,
    `Limited by: ${RULE[res.limiting] || res.limiting}`,
  ];
  if (Number.isFinite(amount) && amount > 0) {
    lines.push(amount <= res.room + 0.5 ? `✅ ${money(amount)} fits your rules.` : `⚠️ ${money(amount)} is ${money(amount - res.room)} more than your rules allow.`);
  }
  if (days != null && days >= 0 && days <= 7) lines.push(`Earnings in ${days} days: volatility ahead.`);
  lines.push("Suggested max from your own rules, not advice.", link(app, `canibuy/${encodeURIComponent(sym)}`));
  return lines.join("\n");
}

function events(data, today, app) {
  const end = new Date(Date.parse(`${today}T00:00:00Z`) + 7 * 864e5).toISOString().slice(0, 10);
  const inWeek = (d) => d && d >= today && d <= end;
  const out = [];
  for (const r of data.rows || []) {
    if (inWeek(r.next_earnings?.date)) out.push([r.next_earnings.date, `${r.symbol} earnings${r.next_earnings.hour === "bmo" ? " (before open)" : r.next_earnings.hour === "amc" ? " (after close)" : ""}`]);
    if (inWeek(r.next_dividend?.ex_date)) out.push([r.next_dividend.ex_date, `${r.symbol} ex-dividend${r.next_dividend.amount ? ` ${money(r.next_dividend.amount, r.next_dividend.currency || r.currency, 2)}` : ""}${r.next_dividend.estimated ? " (est.)" : ""}`]);
  }
  for (const m of data.macro || []) if (inWeek(m.date)) out.push([m.date, `${m.kind === "ecb" ? "ECB" : m.kind === "fomc" ? "Fed (FOMC)" : m.kind} rate decision`]);
  if (!out.length) return `Nothing on your calendar in the next 7 days.\n${link(app, "calendar")}`;
  out.sort((a, b) => a[0].localeCompare(b[0]));
  const day = (d) => new Date(`${d}T12:00:00Z`).toLocaleDateString("en-GB", { weekday: "short", day: "numeric", month: "short", timeZone: "UTC" });
  return ["Next 7 days:", ...out.map(([d, t]) => `${day(d)} · ${t}`), link(app, "calendar")].join("\n");
}

function levels(data, sym, detail, app) {
  if (!sym) return needTicker("levels");
  const r = findRow(data, sym);
  if (!r) return notOnList(sym);
  const zones = detail?.weekly?.levels?.zones || [];
  const near = (role) => zones.filter((z) => z.role === role).sort((a, b) => Math.abs(a.distance_pct) - Math.abs(b.distance_pct))[0];
  const z = (x, word) => (x ? `${word} ${money(x.low, r.currency, 2)}–${money(x.high, r.currency, 2)} (${num(Math.abs(x.distance_pct), 1)} % ${x.role === "support" ? "below" : "above"}, ${x.touches} touches, ${(x.tfs || []).join("·")})` : `No ${word.toLowerCase()} nearby.`);
  return [`${sym} at ${money(r.price, r.currency, 2)}`, z(near("support"), "Support"), z(near("resistance"), "Resistance"), link(app, `ticker/${encodeURIComponent(sym)}`)].join("\n");
}

function thesis(data, sym, app) {
  if (!sym) return needTicker("thesis");
  const r = findRow(data, sym);
  if (!r) return notOnList(sym);
  const th = (data.pf?.thesis || []).find((x) => x.symbol === sym);
  if (!th) return `No thesis for ${sym} yet. Write it in the app.\n${link(app, `thesis/${encodeURIComponent(sym)}`)}`;
  const res = evaluate(th.rules || [], r.metrics || {});
  const st = thesisStatus(res);
  const head = { intact: "✅ Thesis intact", broken1: "⚠️ 1 rule broken", broken: "❌ Several rules broken", unknown: "Thesis: no data yet", none: "No automatic rules" }[st];
  return [
    `${sym}: ${head}`,
    th.why ? `Why: ${th.why}` : null,
    ...res.map((x) => `${x.ok === false ? "❌" : x.ok ? "✅" : "–"} ${x.metric.replace(/_/g, " ")} ${x.op === ">=" ? "≥" : "≤"} ${smart(x.value)} (now ${smart(x.actual)})`),
    link(app, `thesis/${encodeURIComponent(sym)}`),
  ].filter(Boolean).join("\n");
}

function news(data, sym, detail, app) {
  if (!sym) return needTicker("news");
  if (!findRow(data, sym)) return notOnList(sym);
  const items = (detail?.fundamentals?.news || []).slice(0, 5);
  if (!items.length) return `No recent headlines for ${sym}.`;
  return [`${sym} — latest headlines:`, ...items.map((n) => `• ${n.headline || n.title}${n.source ? ` (${n.source})` : ""}`), link(app, `ticker/${encodeURIComponent(sym)}`)].join("\n");
}

function health(data, now, app) {
  const last = (data.runs || []).find((r) => r.job === "daily");
  if (!last) return "No update has run yet.";
  const hours = Math.round((now - Date.parse(last.finished_at)) / 36e5);
  const failed = Object.entries(last.sources || {}).filter(([, v]) => v && v.ok === false).map(([k]) => k.replace(/_/g, " "));
  const c = last.counts || {};
  return [
    `Last update: ${last.status} · ${hours} h ago`,
    `${c.scored ?? 0} of ${c.tickers ?? 0} tickers scored${c.errors ? `, ${c.errors} without prices` : ""}`,
    failed.length ? `Sources with problems: ${failed.join(", ")}` : "All data sources working.",
    link(app, "more/health"),
  ].join("\n");
}

/** The reply for one message. data holds only what needs(cmd) asked for. */
function answer({ cmd, args, raw }, data, { app, today = new Date().toISOString().slice(0, 10), now = Date.now() } = {}) {
  switch (cmd) {
    case "score": return score(data, args[0], app);
    case "portfolio": return portfolio(data, app);
    case "canibuy": return canibuy(data, args[0], args[1], app);
    case "events": return events(data, today, app);
    case "levels": return levels(data, args[0], data.detail, app);
    case "thesis": return thesis(data, args[0], app);
    case "news": return news(data, args[0], data.detail, app);
    case "health": return health(data, now, app);
    case "gaps": return "The gap finder comes in a later phase (needs ETF look-through).";
    case "unknown": return `I don't know /${raw}.\n\n${help()}`;
    default: return help();
  }
}

return { COMMANDS, needs, parseCommand, parseAmount, help, score, portfolio, canibuy, events, levels, thesis, news, health, answer };
})();

// ---- backend/functions/telegram-bot/server.js
/* Telegram webhook (Supabase Edge Function "telegram-bot"). Read-only; answers ONLY the owner's chat.
 * - Telegram sends the secret header we registered (derived from the bot token: sha256("<token>:webhook")),
 *   so nobody else can call this function with fake messages.
 * - Data is read with the service role key that Supabase gives every function; only the owner's rows.
 * - Logs the command name only (never tickers, amounts or replies).
 * Secrets (Edge Functions → Secrets): TELEGRAM_BOT_TOKEN, TELEGRAM_CHAT_ID. Verify JWT: OFF. */
const { parseCommand, needs, answer } = __core;

const APP_URL = "https://stock-tracker-dgz.pages.dev";

async function webhookSecret(token) {
  const buf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(`${token}:webhook`));
  return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("").slice(0, 64);
}

async function rest(path) {
  const key = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  const r = await fetch(`${Deno.env.get("SUPABASE_URL")}/rest/v1/${path}`, { headers: { apikey: key, Authorization: `Bearer ${key}` } });
  if (!r.ok) throw new Error(`read ${r.status}`);
  return r.json();
}

/** Only what the command needs, only the owner's rows (single-user app: the watchlist's owner). */
async function load(parts, symbol) {
  const owner = (await rest("watchlist?select=user_id&limit=1"))[0]?.user_id;
  if (!owner) return { rows: [] };
  const mine = `user_id=eq.${owner}`;
  const data = {};
  if (parts.includes("rows")) {
    const [wl, sc] = await Promise.all([rest(`watchlist?select=*&${mine}`), rest(`latest_scores?select=*&${mine}`)]);
    const by = Object.fromEntries(sc.map((s) => [s.symbol, s]));
    data.rows = wl.map((w) => ({ ...(by[w.symbol.toUpperCase()] || {}), ...w, symbol: w.symbol.toUpperCase() }));
  }
  if (parts.includes("pf")) {
    const [tx, ps, rs, th] = await Promise.all([rest(`transactions?select=*&${mine}&order=date`), rest(`portfolio_settings?select=*&${mine}`),
      rest(`risk_settings?select=*&${mine}`), rest(`thesis?select=*&${mine}`)]);
    data.pf = { transactions: tx, settings: ps[0] || null, risk: rs[0] || null, thesis: th };
  }
  if (parts.includes("market")) data.market = (await rest("market_snapshot?select=data&id=eq.latest"))[0]?.data || null;
  if (parts.includes("macro")) data.macro = (await rest("market_snapshot?select=data&id=eq.macro"))[0]?.data?.events || [];
  if (parts.includes("runs")) data.runs = await rest("job_runs?select=*&job=eq.daily&order=started_at.desc&limit=1");
  if (parts.includes("detail") && symbol) data.detail = (await rest(`ticker_detail?select=weekly,fundamentals&${mine}&symbol=eq.${encodeURIComponent(symbol)}`))[0] || null;
  return data;
}

async function handle(req) {
  if (req.method !== "POST") return new Response("ok");
  const token = Deno.env.get("TELEGRAM_BOT_TOKEN");
  const chat = Deno.env.get("TELEGRAM_CHAT_ID");
  if (!token || !chat) return new Response("not configured", { status: 503 });
  if (req.headers.get("X-Telegram-Bot-Api-Secret-Token") !== (await webhookSecret(token))) return new Response("forbidden", { status: 401 });
  const update = await req.json().catch(() => null);
  const msg = update?.message;
  if (!msg?.text) return new Response("ok");
  if (String(msg.chat?.id) !== String(chat)) { // strangers get no answer at all
    console.log("bot: ignored a message from another chat");
    return new Response("ok");
  }
  const c = parseCommand(msg.text);
  let text;
  try {
    const symbol = /^[A-Z0-9.\-^=]{1,20}$/.test(c.args[0] || "") ? c.args[0] : null;
    if (c.args[0] && !symbol) c.args[0] = "";
    text = answer(c, await load(needs(c.cmd), symbol), { app: APP_URL });
  } catch (e) {
    console.log("bot: failed", c.cmd, e?.message ? "(read error)" : "");
    text = "Sorry, I couldn't read your data just now. Try again in a minute, or open the app.";
  }
  await fetch(`https://api.telegram.org/bot${token}/sendMessage`, {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ chat_id: chat, text: text.slice(0, 4000), disable_web_page_preview: true }),
  });
  console.log("bot: answered", c.cmd); // command name only
  return new Response("ok");
}

Deno.serve(handle);
